// Classes de la Ternelande (dark fantasy, « La Dîme ») : dix classes, deux sous-classes chacune.
// Caractéristiques du genre : 0 Vigueur, 1 Agilité, 2 Endurance, 3 Savoir, 4 Volonté, 5 Présence.
// La magie se paie en souvenirs (bible, section 4) : chaque sort dit son niveau, et s'il rend flou un souvenir.
// Les textes sont lus par les joueurs : aucun secret du canon (shared/canon/dark-fantasy.ts) ici.
import type { ActionType, CharacterClass, Power, Recharge, Subclass } from "./rules";

const P = (level: number, name: string, action: ActionType, recharge: Recharge, effect: string, extra: Partial<Power> = {}): Power => ({ level, name, action, recharge, effect, ...extra });
const S = (id: string, name: string, pitch: string, description: string, powers: Power[]): Subclass => ({ id, name, pitch, description, powers });

/** Le niveau de sort d'un pouvoir, et ce qu'il coûte en souvenirs. */
const sort = (n: number) =>
  n >= 6
    ? ` Sort de niveau ${n}. Ce pouvoir rend flou un souvenir.`
    : n >= 3
      ? ` Sort de niveau ${n}. S'il est ton premier sort de niveau 3 ou plus depuis ton repos long, ce pouvoir rend flou un souvenir.`
      : ` Sort de niveau ${n}, sans prix.`;

const PRIX =
  "Tes tours et tes sorts de niveau 1 et 2 ne coûtent rien. Le premier sort de niveau 3 ou plus que tu lances après un repos long rend flou un de tes souvenirs intacts, au choix ; les suivants ne coûtent rien jusqu'au repos long. Un sort de niveau 6 ou plus rend flou un souvenir à chaque fois. Si tu n'as plus de souvenir intact, tu uses un souvenir flou : il est perdu. Chaque pouvoir dit son niveau de sort.";

